func isRelativeImportSpec(importingPath, spec string) bool {
	switch strings.ToLower(filepath.Ext(importingPath)) {
	case ".js", ".jsx", ".ts", ".tsx":
		return strings.HasPrefix(spec, "./") || strings.HasPrefix(spec, "../")
	case ".py":
		return strings.HasPrefix(spec, ".")
	default:
		return false
	}
}

