// symbolMatchBody is the source of one matched definition, read for the answers FIX A and FIX B
// return in place of a refusal.
type symbolMatchBody struct {
	Name      string `json:"name"`
	Kind      string `json:"kind,omitempty"`
	FilePath  string `json:"file_path"`
	StartLine int    `json:"start_line"`
	EndLine   int    `json:"end_line"`
	Source    string `json:"source,omitempty"`
	Elided    bool   `json:"elided,omitempty"`
	// UnitEndLine is the symbol's true last line when the cap clipped the body, so the note can tell
	// the caller where to resume instead of only that something is missing.
	UnitEndLine int `json:"unit_end_line,omitempty"`
}

// symbolMatchBodies reads a compact body for the first `limit` records. A body that cannot be read
// (file gone, binary, oversized) is simply omitted: the locator list above it is still a complete
// answer, and a missing body must never turn an answer back into a refusal.
func symbolMatchBodies(repoRoot string, matches []sem.SymbolRecord, limit int) []symbolMatchBody {
	if repoRoot == "" || limit <= 0 || len(matches) == 0 {
		return nil
	}
	read := newRepoLineReader(repoRoot)
	bodies := make([]symbolMatchBody, 0, minSymbolInt(limit, len(matches)))
	for _, symbol := range matches {
		if len(bodies) >= limit {
			break
		}
		if symbol.FilePath == "" || symbol.StartLine <= 0 {
			continue
		}
		lines, ok := read(symbol.FilePath)
		if !ok || symbol.StartLine > len(lines) {
			continue
		}
		start := symbol.StartLine
		end := symbol.EndLine
		if end < start {
			end = start
		}
		if end > len(lines) {
			end = len(lines)
		}
		elided, unitEnd := false, 0
		if end-start+1 > symbolMatchBodyMaxLines {
			unitEnd = end
			end = start + symbolMatchBodyMaxLines - 1
			elided = true
		}
		bodies = append(bodies, symbolMatchBody{
			Name:        symbolRefDisplayName(symbol),
			Kind:        symbol.Kind,
			FilePath:    symbol.FilePath,
			StartLine:   start,
			EndLine:     end,
			Source:      strings.Join(lines[start-1:end], "\n"),
			Elided:      elided,
			UnitEndLine: unitEnd,
		})
	}
	if len(bodies) == 0 {
		return nil
	}
	return bodies
}

func minSymbolInt(left, right int) int {
	if left < right {
		return left
	}
	return right
}

// writeSymbolMatchBodies prints the bodies under a locator list, each line in a NUMBERED gutter.
//
// The search payload's bodies are deliberately unnumbered — an agent copies them verbatim as an Edit
// anchor, and a gutter breaks the anchor. These are not those. `def`, `callers` and `neighbors` answer
// "where is it", and the measured failure mode is the opposite one: carbon's agent got an unnumbered
// body, could not tell which line was which, piped it through `head -80` and lost the line it needed.
// A navigation answer wants coordinates; an edit source wants fidelity. Two outputs, two rules.
func writeSymbolMatchBodies(out interface {
	Write([]byte) (int, error)
}, bodies []symbolMatchBody) {
	// The single place repository SOURCE is printed with a line-number gutter, and
	// the only sink `def` reaches that its own writer wrap does not cover — so the
	// wrap is made here, where all three callers pass through. Wrapping twice is
	// harmless; see termsafe.NewWriter.
	out = termsafe.NewWriter(out)
	for _, body := range bodies {
		// The locator above each body is one line, so its fields get the stricter
		// escape; the body itself keeps its newlines, being real layout.
		fmt.Fprintf(out, "\n%s:%d-%d %s", termsafe.Line(body.FilePath), body.StartLine, body.EndLine,
			termsafe.Line(body.Name))
		if body.Kind != "" {
			fmt.Fprintf(out, " [%s]", termsafe.Line(body.Kind))
		}
		fmt.Fprintln(out)
		writeNumberedSource(out, body.Source, body.StartLine)
		if body.Elided {
			// Actionable, not merely honest: the caller is told where the body continues AND the exact
			// invocation that resumes it, because "output truncated" is what sent carbon to grep.
			fmt.Fprintf(out, "  …continues to line %d — rerun with --from %d\n",
				body.UnitEndLine, body.EndLine+1)
	}

	if len(response.Matches) == 0 {
		appendVariant(
			fmt.Sprintf("No symbols matched %q; check the name with `search`.\n", response.Query),
			fmt.Sprintf("No match: %s\n", response.Query),
		)
	} else if response.DisambiguationRequired {
		appendVariant(
			fmt.Sprintf("Ambiguous %q: %d definitions; rerun with the selector shown.\n", response.Query, response.FocusMatchesTotal),
			fmt.Sprintf("Ambiguous: %d; use --symbol <file>:<line>.\n", response.FocusMatchesTotal),
		)
		definitions := make([]neighborEndpoint, 0, len(response.Matches))
		for _, match := range response.Matches {
			definitions = append(definitions, match.Symbol)
		}
		selectors := disambiguationSelectors(definitions)
		for index, definition := range definitions {
			line := "- " + formatNeighborEndpoint(definition)
			if selectors[index] != "" {
				appendVariant(line+"  "+selectors[index]+"\n", line+"\n")
				continue
			}
			appendVariant(line + "\n")
		}
	} else {
		focus := response.Matches[0].Symbol
		appendVariant(
			"Focus: "+formatNeighborEndpoint(focus)+"\n",
			fmt.Sprintf("F %s:%d %s\n", focus.FilePath, focus.StartLine, endpointDisplayName(focus)),
			fmt.Sprintf("F %s:%d\n", focus.FilePath, focus.StartLine),
		)
	}

	// Under a hard byte cap, only the diagnostics that could have affected THIS
	// answer are worth a line; the rest is one count.
	appendVariant(compactCompletenessLine(scope, response.Stats))
	if coverageIssue {
		for _, warning := range scope.InScopeWarnings {
			appendVariant(fmt.Sprintf("W %s%s\n", warning.Code, agentDiagnosticPath(warning.FilePath)))
		}
		for _, failure := range scope.InScopeFailures {
			appendVariant(fmt.Sprintf("F %s%s\n", failure.Code, agentDiagnosticPath(failure.FilePath)))
		}
	}
	if response.endpointTruncated {
		appendVariant("!neighbor-list-truncated; raise --limit\n", "!neighbors-truncated\n")
	}
	cacheState := "miss"
	if response.IndexCacheHit {
		cacheState = "hit"
	}
	appendVariant(fmt.Sprintf("I:%s/%d Q:%d T:%d\n", cacheState, response.IndexLatencyMS, response.QueryLatencyMS, response.TotalLatencyMS))

	if len(response.Matches) > 0 && !response.DisambiguationRequired {
		match := response.Matches[0]
		for _, edge := range match.Incoming {
			appendVariant(compactNeighborEdge("<", edge))
		}
		for _, edge := range match.Outgoing {
			appendVariant(compactNeighborEdge(">", edge))
		}
		// Even at the tightest cap, an unqueried direction must not read as an
		// empty one. `<-only` / `>-only` costs 8 bytes and prevents the reader
		// concluding the graph has no callees.
		if !neighborDirectionQueried(response.Direction, "out") {
			appendVariant(">?not-queried\n")
		}
		if !neighborDirectionQueried(response.Direction, "in") {
			appendVariant("<?not-queried\n")
		}
		if len(match.Paths) > 0 {
			pathCount := len(match.Incoming) * len(match.Outgoing)
			appendVariant(fmt.Sprintf("Paths: %dx1x%d=%d (endpoints above)\n", len(match.Incoming), len(match.Outgoing), pathCount))
		}
	}
	return output.Bytes()
}

func compactNeighborEdge(direction string, edge neighborEdge) string {
	annotation := ""
	if edge.Resolution != "" {
		annotation = " [" + edge.Resolution + "]"
	}
	// The call site is the location a reader needs; the definition line is
	// still reported so the caller can be found as a symbol.
	return fmt.Sprintf("%s %s%s\n", direction, formatCallSiteLocation(edge.Endpoint, edge.CallSite), annotation)
}

