func stripSQLComments(content string) string {
	b := []byte(content)
	n := len(b)
	for i := 0; i < n; {
		switch b[i] {
		case '\'':
			i++
			for i < n {
				if b[i] == '\'' {
					if i+1 < n && b[i+1] == '\'' {
						i += 2
						continue
					}
					i++
					break
				}
				i++
			}
		case '$':
			if tag, ok := dollarQuoteTag(content, i); ok {
				closeRel := strings.Index(content[i+len(tag):], tag)
				if closeRel < 0 {
					return string(b)
				}
				i = i + len(tag) + closeRel + len(tag)
			} else {
				i++
			}
		case '-':
			if i+1 < n && b[i+1] == '-' {
				for i < n && b[i] != '\n' {
					b[i] = ' '
					i++
				}
			} else {
				i++
			}
		case '/':
			if i+1 < n && b[i+1] == '*' {
				b[i] = ' '
				b[i+1] = ' '
				i += 2
				for i < n {
					if b[i] == '*' && i+1 < n && b[i+1] == '/' {
						b[i] = ' '
						b[i+1] = ' '
						i += 2
						break
					}
					if b[i] != '\n' && b[i] != '\r' {
						b[i] = ' '
					}
					i++
				}
			} else {
				i++
			}
		default:
			i++
		}
	}
	return string(b)
}

