func normalizeSQLDottedName(content string) string {
	var parts []string
	for _, part := range strings.Split(content, ".") {
		part = strings.TrimSpace(part)
		part = strings.Trim(part, "`\"")
		if part != "" {
			parts = append(parts, part)
		}
	}
	return strings.Join(parts, ".")
}

